def _build_auth_crud_edge_kinds() -> dict[str, tuple[str, str]]:
    edge_kinds: dict[str, tuple[str, str]] = {}

    role_families = {
        "AliCloud": "AliCloud",
        "Approle": "AppRole",
        "Aws": "AWS",
        "Azure": "Azure",
        "Cf": "Cloud Foundry",
        "Gcp": "GCP",
        "JwtOidc": "JWT/OIDC",
        "Kubernetes": "Kubernetes",
        "Oci": "OCI",
        "Saml": "SAML",
        "Scep": "SCEP",
        "Spiffe": "SPIFFE",
        "TlsCert": "TLS Certificate",
        "Token": "Token",
    }
    for family, auth_method_type in role_families.items():
        edge_kinds[f"Vault_Auth{family}ListRoles"] = ("Vault_ListRoles", auth_method_type)
        edge_kinds[f"Vault_Auth{family}ReadRole"] = ("Vault_ReadRole", auth_method_type)
        edge_kinds[f"Vault_Auth{family}ManageRole"] = ("Vault_ManageRole", auth_method_type)

    user_families = {
        "Github": "GitHub",
        "Ldap": "LDAP",
        "Okta": "Okta",
        "Radius": "RADIUS",
        "Userpass": "UserPass",
    }
    for family, auth_method_type in user_families.items():
        edge_kinds[f"Vault_Auth{family}ListUsers"] = ("Vault_AuthListUsers", auth_method_type)
        edge_kinds[f"Vault_Auth{family}ReadUser"] = ("Vault_AuthReadUser", auth_method_type)
        edge_kinds[f"Vault_Auth{family}ManageUser"] = ("Vault_AuthManageUser", auth_method_type)

    group_families = {
        "Kerberos": "Kerberos",
        "Ldap": "LDAP",
        "Okta": "Okta",
    }
    for family, auth_method_type in group_families.items():
        edge_kinds[f"Vault_Auth{family}ListGroups"] = ("Vault_AuthListGroups", auth_method_type)
        edge_kinds[f"Vault_Auth{family}ReadGroup"] = ("Vault_AuthReadGroup", auth_method_type)
        edge_kinds[f"Vault_Auth{family}ManageGroup"] = ("Vault_AuthManageGroup", auth_method_type)

    # GitHub teams are the GitHub auth method's group-like principal surface.
    edge_kinds["Vault_AuthGithubReadTeam"] = ("Vault_AuthReadGroup", "GitHub")
    edge_kinds["Vault_AuthGithubManageTeam"] = ("Vault_AuthManageGroup", "GitHub")

    return edge_kinds


AUTH_CRUD_EDGE_KINDS = _build_auth_crud_edge_kinds()


def _build_secrets_crud_edge_kinds() -> dict[str, tuple[str, str]]:
    edge_kinds: dict[str, tuple[str, str]] = {}

    role_families = {
        "Aws": "AWS",
        "Azure": "Azure",
        "Database": "Database",
        "Kubernetes": "Kubernetes",
        "Pki": "PKI",
        "Ssh": "SSH",
        "Terraform": "Terraform",
    }
    for family, engine_type in role_families.items():
        edge_kinds[f"Vault_{family}ListRoles"] = ("Vault_ListRoles", engine_type)
        edge_kinds[f"Vault_{family}ReadRole"] = ("Vault_ReadRole", engine_type)
        edge_kinds[f"Vault_{family}ManageRole"] = ("Vault_ManageRole", engine_type)

    static_role_families = {
        "Aws": "AWS",
        "Azure": "Azure",
        "Database": "Database",
        "Ldap": "LDAP",
    }
    for family, engine_type in static_role_families.items():
        edge_kinds[f"Vault_{family}ListStaticRoles"] = ("Vault_ListRoles", engine_type)
        edge_kinds[f"Vault_{family}ReadStaticRole"] = ("Vault_ReadRole", engine_type)
        edge_kinds[f"Vault_{family}ManageStaticRole"] = ("Vault_ManageRole", engine_type)

    key_families = {
        "GcpKms": "GCP KMS",
        "Pki": "PKI",
        "Totp": "TOTP",
        "Transit": "Transit",
    }
    for family, engine_type in key_families.items():
        edge_kinds[f"Vault_{family}ListKeys"] = ("Vault_ListKeys", engine_type)
        edge_kinds[f"Vault_{family}ReadKey"] = ("Vault_ReadKey", engine_type)
        edge_kinds[f"Vault_{family}ManageKey"] = ("Vault_ManageKey", engine_type)

    return edge_kinds


SECRETS_CRUD_EDGE_KINDS = _build_secrets_crud_edge_kinds()

