def normalize_string_list(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, str):
        items = [item.strip() for item in value.split(",")]
    elif isinstance(value, (list, tuple, set)):
        items = [str(item).strip() for item in value]
    else:
        items = [str(value).strip()]
    return list(dict.fromkeys(item for item in items if item))


def database_plugin_profile(plugin_name: Any) -> dict[str, Any]:
    normalized_name = str(plugin_name or "").strip().lower()
    profile = DATABASE_PLUGIN_PROFILES.get(normalized_name)
    if profile is None:
        return {
            "supports_root_rotation": None,
            "supports_dynamic_roles": None,
            "supports_static_roles": None,
            "supported_credential_types": [],
            "capability_source": "Unknown Or Custom Plugin",
        }

    return {
        **profile,
        "supported_credential_types": list(profile.get("supported_credential_types", [])),
        "capability_source": "HashiCorp Database Capability Matrix",
    }


def database_plugin_profile_ui_properties(profile: dict[str, Any]) -> dict[str, Any]:
    properties: dict[str, Any] = {}
    for field, label in (
        ("supports_root_rotation", "Supports Root Rotation"),
        ("supports_dynamic_roles", "Supports Dynamic Roles"),
        ("supports_static_roles", "Supports Static Roles"),
    ):
        value = profile.get(field)
        if value is not None:
            properties[label] = value

    credential_types = normalize_string_list(profile.get("supported_credential_types"))
    if credential_types:
        properties["Supported Credential Types"] = credential_types

    capability_source = str(profile.get("capability_source") or "").strip()
    if capability_source:
        properties["Plugin Capability Source"] = capability_source
    return properties


# ---------------------------------------------------------------------------
# API Client
# ---------------------------------------------------------------------------


class VaultClient:
    """Minimal Vault HTTP API client."""

    def __init__(self, addr: str, token: str, namespace: str = ""):
        self.addr = addr.rstrip("/")
        self.token = token
        self.namespace = str(namespace or "").strip().strip("/")
        if self.namespace.lower() == "root":
            self.namespace = ""
        self._rate_delay = 0.02  # 50 req/s default

    def _request(self, method: str, path: str, retries: int = 3) -> Any | None:
        url = f"{self.addr}/v1/{path.lstrip('/')}"
        req = Request(url, method=method)
        req.add_header("X-Vault-Token", self.token)
        req.add_header("Accept", "application/json")
        if self.namespace:
            req.add_header("X-Vault-Namespace", self.namespace)

        for attempt in range(retries):
            try:
                time.sleep(self._rate_delay)
                with urlopen(req, timeout=30) as resp:
                    body = resp.read().decode("utf-8")
                    return json.loads(body) if body else {}
            except HTTPError as e:
                if e.code == 404:
                    return None
                if e.code == 403:
                    log.warning("403 Forbidden: %s %s", method, path)
                    return None
                if e.code == 429 or e.code >= 500:
                    wait = 2 ** attempt
                    log.warning("%d on %s, retrying in %ds", e.code, path, wait)
                    time.sleep(wait)
                    continue
                raise
            except URLError as e:
                if attempt < retries - 1:
                    time.sleep(2 ** attempt)
                    continue
                raise
        return None

    def read_raw(self, path: str) -> Any | None:
        return self._request("GET", path)

    def read(self, path: str) -> dict | None:
        resp = self.read_raw(path)
        return resp.get("data", resp) if isinstance(resp, dict) else None

    def list_raw(self, path: str) -> Any | None:
        resp = self._request("LIST", f"{path}?list=true")
        if resp is None or (
            isinstance(resp, dict) and "data" not in resp and "keys" not in resp
        ):
            # Try GET with list=true for endpoints that need it.
            resp = self._request("GET", f"{path}?list=true")
        return resp

    @staticmethod
    def _list_response_names(resp: Any | None) -> list[str]:
        data = resp.get("data", resp) if isinstance(resp, dict) else resp
        if isinstance(data, dict):
            return data.get("keys", [])
        if isinstance(data, list):
            names: list[str] = []
            for item in data:
                if isinstance(item, str):
                    names.append(item)
                    continue
                if not isinstance(item, dict):
                    continue
                name = item.get("name") or item.get("role_name")
                if name:
                    names.append(str(name))
            return names
        return []

    def list(self, path: str) -> list:
        return self._list_response_names(self.list_raw(path))


# ---------------------------------------------------------------------------
# HCL Policy Parser
# ---------------------------------------------------------------------------


def _hcl_balanced_body(text: str, open_index: int) -> tuple[str, int] | None:
    """Return a brace-delimited HCL body while ignoring quoted braces and comments."""
    depth = 0
    quote = ""
    escaped = False
    line_comment = False
    block_comment = False

    for index in range(open_index, len(text)):
        character = text[index]
        following = text[index + 1] if index + 1 < len(text) else ""

        if line_comment:
            if character == "\n":
                line_comment = False
            continue
        if block_comment:
            if character == "*" and following == "/":
                block_comment = False
            continue
        if quote:
            if escaped:
                escaped = False
            elif character == "\\":
                escaped = True
            elif character == quote:
                quote = ""
            continue

        if character in {'"', "'"}:
            quote = character
            continue
        if character == "#" or (character == "/" and following == "/"):
            line_comment = True
            continue
        if character == "/" and following == "*":
            block_comment = True
            continue
        if character == "{":
            depth += 1
        elif character == "}":
            depth -= 1
            if depth == 0:
                return text[open_index + 1:index], index + 1
    return None


def _hcl_assignment_list(block: str, field_name: str) -> list[str]:
    match = re.search(rf'\b{re.escape(field_name)}\s*=\s*\[([^\]]*)\]', block, re.DOTALL)
    if not match:
        return []
    return list(dict.fromkeys(
        item
        for item in re.findall(r'["\']([^"\']+)["\']', match.group(1))
        if item
    ))


def _hcl_without_comments(text: str) -> str:
    result: list[str] = []
    quote = ""
    escaped = False
    line_comment = False
    block_comment = False
    index = 0
    while index < len(text):
        character = text[index]
        following = text[index + 1] if index + 1 < len(text) else ""
        if line_comment:
            if character == "\n":
                line_comment = False
                result.append(character)
            index += 1
            continue
        if block_comment:
            if character == "*" and following == "/":
                block_comment = False
                index += 2
            else:
                index += 1
            continue
        if quote:
            result.append(character)
            if escaped:
                escaped = False
            elif character == "\\":
                escaped = True
            elif character == quote:
                quote = ""
            index += 1
            continue
        if character in {'"', "'"}:
            quote = character
            result.append(character)
            index += 1
            continue
        if character == "#" or (character == "/" and following == "/"):
            line_comment = True
            index += 2 if character == "/" else 1
            continue
        if character == "/" and following == "*":
            block_comment = True
            index += 2
            continue
        result.append(character)
        index += 1
    return "".join(result)


def _hcl_parameter_constraint_summary(
    block: str,
    field_name: str,
) -> tuple[list[str], list[str], dict[str, list[str]]]:
    match = re.search(rf'\b{re.escape(field_name)}\s*=\s*\{{', block)
    if not match:
        return [], [], {}
    result = _hcl_balanced_body(block, match.end() - 1)
    if not result:
        return [], [], {}

    body, _ = result
    names: list[str] = []
    value_constrained: list[str] = []
    parameter_values: dict[str, list[str]] = {}
    assignments = re.finditer(
        r'(?m)^\s*(?:"([^"]+)"|([A-Za-z0-9_.*/+-]+))\s*=\s*(\[[^\]]*\])',
        body,
    )
    for assignment in assignments:
        name = assignment.group(1) or assignment.group(2)
        if name not in names:
            names.append(name)
        raw_values = assignment.group(3)
        values = list(dict.fromkeys(
            value
            for value in re.findall(r'["\']([^"\']+)["\']', raw_values)
            if value
        ))
        parameter_values[name] = values
        if raw_values.strip() != "[]" and name not in value_constrained:
            value_constrained.append(name)
    return names, value_constrained, parameter_values


def _parsed_policy_path(path: Any, data: dict[str, Any]) -> dict[str, Any]:
    def parameter_names_and_constraints(
        value: Any,
    ) -> tuple[list[str], list[str], dict[str, list[str]]]:
        if not isinstance(value, dict):
            return normalize_string_list(value), [], {}
        names = normalize_string_list(list(value.keys()))
        constrained = [
            name for name in names
            if value.get(name) not in (None, [], {})
        ]
        parameter_values = {
            name: normalize_string_list(value.get(name))
            for name in names
        }
        return names, constrained, parameter_values

    allowed_parameters, allowed_constraints, allowed_parameter_values = (
        parameter_names_and_constraints(
            data.get("allowed_parameters")
        )
    )
    denied_parameters, denied_constraints, denied_parameter_values = (
        parameter_names_and_constraints(
            data.get("denied_parameters")
        )
    )
    return {
        "path": str(path),
        "capabilities": normalize_string_list(data.get("capabilities")),
        "required_parameters": normalize_string_list(data.get("required_parameters")),
        "allowed_parameters": allowed_parameters,
        "denied_parameters": denied_parameters,
        "value_constrained_parameters": sorted(set(
            normalize_string_list(data.get("value_constrained_parameters"))
            + allowed_constraints
            + denied_constraints
        )),
        "allowed_parameter_values": allowed_parameter_values,
        "denied_parameter_values": denied_parameter_values,
    }


def parse_hcl_policy(rules: str) -> list[dict]:
    """Parse the ACL fields needed for effective access and KV1 constraints."""
    try:
        json_rules = json.loads(rules)
    except (TypeError, ValueError):
        json_rules = None

    if isinstance(json_rules, dict) and isinstance(json_rules.get("path"), dict):
        results = []
        for path, path_data in json_rules["path"].items():
            if isinstance(path_data, dict):
                results.append(_parsed_policy_path(path, path_data))
        return results

    results: list[dict[str, Any]] = []
    header = re.compile(r'\bpath\s+"((?:\\.|[^"])*)"\s*\{')
    search_index = 0
    while match := header.search(rules, search_index):
        result = _hcl_balanced_body(rules, match.end() - 1)
        if not result:
            break
        block, search_index = result
        block = _hcl_without_comments(block)
        capabilities = _hcl_assignment_list(block, "capabilities")
        if not capabilities:
            continue
        (
            allowed_parameters,
            allowed_value_constraints,
            allowed_parameter_values,
        ) = _hcl_parameter_constraint_summary(
            block,
            "allowed_parameters",
        )
        (
            denied_parameters,
            denied_value_constraints,
            denied_parameter_values,
        ) = _hcl_parameter_constraint_summary(
            block,
            "denied_parameters",
        )
        results.append(_parsed_policy_path(match.group(1), {
            "capabilities": capabilities,
            "required_parameters": _hcl_assignment_list(block, "required_parameters"),
            "allowed_parameters": allowed_parameter_values or allowed_parameters,
            "denied_parameters": denied_parameter_values or denied_parameters,
            "value_constrained_parameters": allowed_value_constraints + denied_value_constraints,
        }))
    return results


def path_matches_mount(policy_path: str, mount_path: str) -> bool:
    """Check if a policy path pattern covers a mount path.

    policy_path: e.g., "kv/*", "auth/ldap/*", "*"
    mount_path: e.g., "kv/", "auth/ldap/"
    """
    if policy_path == "*":
        return True

    # Normalize: remove trailing /* or *
    clean_policy = policy_path.rstrip("*").rstrip("/")
    clean_mount = mount_path.rstrip("/")

    # "kv/*" matches mount "kv/"
    # "kv/data/*" matches mount "kv/" (sub-path of mount)
    # "auth/ldap/*" matches mount "auth/ldap/"
    # "sys/auth/*" matches mount... well it's a special case

    return clean_mount == clean_policy or clean_mount.startswith(clean_policy + "/") or clean_policy.startswith(clean_mount + "/") or clean_policy.startswith(clean_mount)


def has_write_caps(caps: list[str]) -> bool:
    return bool(set(caps) & {"create", "update", "delete", "patch", "recover"})


def has_read_caps(caps: list[str]) -> bool:
    return bool(set(caps) & {"read", "list"})


def filter_capabilities(caps: list[str], allowed: set[str]) -> list[str]:
    return [cap for cap in sorted(set(caps)) if cap in allowed]


def get_secrets_engine_kinds(engine_type: str) -> list[str]:
    """Return the base secrets engine kind plus any engine-specific sub-kind."""
    if engine_type not in SUPPORTED_SECRETS_ENGINE_TYPES:
        return ["Vault_SecretsEngine"]

    kinds = []
    if engine_type == "kv":
        kinds.append("Vault_SecretsEngineKv")
    elif engine_type == "aws":
        kinds.append("Vault_SecretsEngineAws")
    elif engine_type == "azure":
        kinds.append("Vault_SecretsEngineAzure")
    elif engine_type == "terraform":
        kinds.append("Vault_SecretsEngineTerraform")
    elif engine_type == "database":
        kinds.append("Vault_SecretsEngineDatabase")
    elif engine_type == "gcp":
        kinds.append("Vault_SecretsEngineGcp")
    elif engine_type == "gcpkms":
        kinds.append("Vault_SecretsEngineGcpKms")
    elif engine_type == "ldap":
        kinds.append("Vault_SecretsEngineLdap")
    elif engine_type == "totp":
        kinds.append("Vault_SecretsEngineTotp")
    elif engine_type == "kubernetes":
        kinds.append("Vault_SecretsEngineKubernetes")
    elif engine_type == "ssh":
        kinds.append("Vault_SecretsEngineSsh")
    elif engine_type == "pki":
        kinds.append("Vault_SecretsEnginePki")
    elif engine_type == "transit":
        kinds.append("Vault_SecretsEngineTransit")
    kinds.append("Vault_SecretsEngine")
    return kinds


