def make_path_token(path: str) -> str:
    """Build a stable, readable suffix for resource node IDs."""
    normalized = path.strip("/") or "root"
    slug = re.sub(r"[^A-Za-z0-9]+", "_", normalized).strip("_") or "root"
    digest = hashlib.sha256(normalized.encode()).hexdigest()[:10]
    return f"{slug[:32]}_{digest}"


def github_slugify(value: Any) -> str:
    text = str(value or "").strip().lower().replace("_", "-").replace(" ", "-")
    while "--" in text:
        text = text.replace("--", "-")
    return text


def policy_path_matches_resource_path(policy_path: str, resource_path: str) -> bool:
    """Match Vault ACL path patterns against a concrete resource path."""
    pattern = policy_path.strip("/")
    actual = resource_path.strip("/")
    if not pattern:
        return actual == ""

    # Vault ACL globs are prefix matches and only supported as the final
    # character of the path; "+" matches a single path segment. Rendered
    # identity-template values must not themselves contain wildcards.
    has_glob = pattern.endswith("*")
    prefix = pattern[:-1] if has_glob else pattern
    segments = prefix.split("/")
    regex_parts = ["^"]

    for idx, segment in enumerate(segments):
        if idx > 0:
            regex_parts.append("/")
        if segment == "+":
            regex_parts.append(r"[^/]+")
        else:
            regex_parts.append(re.escape(segment))

    if has_glob:
        regex_parts.append(".*")
    else:
        regex_parts.append("$")

    return re.match("".join(regex_parts), actual) is not None


def parse_optional_bool(value: Any) -> bool | None:
    """Convert bool-like config values while preserving unknown/missing state."""
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in {"true", "1", "yes", "on"}:
            return True
        if normalized in {"false", "0", "no", "off"}:
            return False
    return None


def spiffe_trust_bundle_format(profile: str, bundle: str) -> str:
    """Infer the bundle format from the configured SPIFFE profile or visible bundle."""
    normalized_profile = str(profile or "").strip()
    normalized_bundle = str(bundle or "").lstrip()
    if normalized_profile == "https_web_pem" or normalized_bundle.startswith("-----BEGIN CERTIFICATE"):
        return "PEM"
    if normalized_profile in {"https_web_bundle", "https_spiffe_bundle"} or normalized_bundle.startswith("{"):
        return "JWKS"
    return "Unknown"


def spiffe_workload_id_from_alias(alias_name: Any, trust_domain: Any) -> str | None:
    """Normalize a SPIFFE entity alias name into the workload ID used by role patterns."""
    normalized_alias = str(alias_name or "").strip()
    if not normalized_alias:
        return None

    normalized_trust_domain = str(trust_domain or "").strip().rstrip("/")
    if normalized_trust_domain and not normalized_trust_domain.startswith("spiffe://"):
        normalized_trust_domain = f"spiffe://{normalized_trust_domain.lstrip('/')}"

    if normalized_trust_domain:
        if normalized_alias == normalized_trust_domain:
            return ""
        trust_domain_prefix = f"{normalized_trust_domain}/"
        if normalized_alias.startswith(trust_domain_prefix):
            return normalized_alias[len(trust_domain_prefix):].strip("/")

    # Existing aliases may already be stored as a workload ID rather than a full SPIFFE ID.
    if normalized_alias.startswith("spiffe://"):
        return None
    return normalized_alias.strip("/")


def spiffe_workload_pattern_matches(pattern: Any, workload_id: Any) -> bool:
    """Match SPIFFE role workload patterns against a normalized workload ID."""
    normalized_pattern = str(pattern or "").strip("/")
    normalized_workload_id = str(workload_id or "").strip("/")
    if not normalized_pattern:
        return normalized_workload_id == ""

    has_glob = normalized_pattern.endswith("*")
    prefix = normalized_pattern[:-1] if has_glob else normalized_pattern
    regex_parts = ["^"]
    for char in prefix:
        if char == "+":
            regex_parts.append(r"[^/]+")
        else:
            regex_parts.append(re.escape(char))
    regex_parts.append(".*" if has_glob else "$")
    return re.match("".join(regex_parts), normalized_workload_id) is not None


def spiffe_workload_pattern_match_type(pattern: Any) -> str:
    normalized_pattern = str(pattern or "")
    return "Wildcard" if "*" in normalized_pattern or "+" in normalized_pattern else "Exact"


def normalize_spiffe_trust_domain(value: Any) -> str:
    """Return a trust domain as a normalized SPIFFE URI prefix."""
    normalized = str(value or "").strip().rstrip("/")
    if normalized and not normalized.startswith("spiffe://"):
        return f"spiffe://{normalized.lstrip('/')}"
    return normalized


def resolve_spiffe_subject_template(subject_template: Any, trust_domain: Any = "") -> str:
    """Resolve a SPIFFE role subject into a full SPIFFE ID when possible."""
    subject = str(subject_template or "").strip()
    if not subject:
        return ""
    if subject.startswith("spiffe://"):
        return subject
    normalized_trust_domain = normalize_spiffe_trust_domain(trust_domain)
    if not normalized_trust_domain:
        return subject
    return f"{normalized_trust_domain}/{subject.lstrip('/')}"


def spiffe_id_trust_domain(value: Any) -> str:
    """Return the trust-domain URI for a concrete SPIFFE ID."""
    match = SPIFFE_ID_PATTERN.fullmatch(str(value or "").strip())
    if not match:
        return ""
    return f"spiffe://{match.group('trust_domain')}"


def parse_spiffe_role_template(value: Any) -> tuple[dict[str, Any], str, str]:
    """Parse SPIFFE role templates from JSON, JSON fragments, or base64 JSON."""
    template = str(value or "").strip()
    if not template:
        return {}, "Missing", ""

    candidates: list[tuple[str, str]] = [(template, "JSON")]
    if not template.startswith("{"):
        candidates.append((f"{{{template}}}", "JSON Fragment"))
    try:
        decoded = base64.b64decode(template, validate=True).decode("utf-8").strip()
    except (ValueError, UnicodeDecodeError):
        decoded = ""
    if decoded:
        candidates.append((decoded, "Base64 JSON"))
        if not decoded.startswith("{"):
            candidates.append((f"{{{decoded}}}", "Base64 JSON Fragment"))

    for candidate, template_format in candidates:
        try:
            parsed = json.loads(candidate)
        except (TypeError, ValueError):
            continue
        if isinstance(parsed, str):
            try:
                parsed = json.loads(parsed)
            except (TypeError, ValueError):
                continue
        if isinstance(parsed, dict):
            return parsed, template_format, json.dumps(parsed, sort_keys=True)
    return {}, "Unparsed", template


def spiffe_role_template_details(data: dict[str, Any], trust_domain: Any = "") -> dict[str, Any]:
    """Extract security-relevant claim information from a SPIFFE role template."""
    template = str(data.get("template") or "").strip()
    parsed_template, template_format, canonical_template = parse_spiffe_role_template(template)
    subject_template = str(parsed_template.get("sub") or "").strip()
    identity_template_references = list(dict.fromkeys(TEMPLATE_PATTERN.findall(canonical_template)))

    resolved_subject_template = resolve_spiffe_subject_template(subject_template, trust_domain)
    subject_scope = ""
    if subject_template:
        subject_scope = "Full SPIFFE ID" if subject_template.startswith("spiffe://") else "Trust Domain Relative Path"

    return {
        "template": template,
        "canonical_template": canonical_template,
        "template_format": template_format,
        "template_claims": sorted(str(key) for key in parsed_template),
        "subject_template": subject_template,
        "resolved_subject_template": resolved_subject_template,
        "subject_scope": subject_scope,
        "subject_is_templated": bool(subject_template and TEMPLATE_PATTERN.search(subject_template)),
        "identity_template_references": identity_template_references,
    }


def to_graph_property_value(value: Any) -> Any:
    """Convert nested API values into graph-safe scalar/list properties."""
    if value is None:
        return None
    if isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, list):
        converted = []
        for item in value:
            if item is None:
                continue
            if isinstance(item, (str, int, float, bool)):
                converted.append(item)
            else:
                converted.append(json.dumps(item, sort_keys=True))
        return converted
    return json.dumps(value, sort_keys=True)


def sanitize_graph_properties(properties: dict[str, Any] | None) -> dict[str, Any]:
    """Drop null property values before emitting OpenGraph payloads."""
    sanitized: dict[str, Any] = {}
    for key, value in (properties or {}).items():
        if value is None:
            continue
        if isinstance(value, list):
            sanitized[key] = [item for item in value if item is not None]
            continue
        sanitized[key] = value
    return sanitized


CERT_NAME_FIELD_LABELS = {
    "commonName": "CN",
    "countryName": "C",
    "localityName": "L",
    "organizationName": "O",
    "organizationalUnitName": "OU",
    "stateOrProvinceName": "ST",
    "emailAddress": "emailAddress",
    "serialNumber": "serialNumber",
}


def format_certificate_name(name: Any) -> str:
    """Render ssl._test_decode_cert subject/issuer tuples into a readable DN."""
    parts: list[str] = []
    for rdn in name or []:
        for field, value in rdn:
            label = CERT_NAME_FIELD_LABELS.get(str(field), str(field))
            parts.append(f"{label}={value}")
    return ", ".join(parts)


def decode_pem_certificate(pem: str) -> dict[str, Any] | None:
    """Decode a PEM certificate with the standard-library ssl helper when available."""
    decoder = getattr(getattr(ssl, "_ssl", None), "_test_decode_cert", None)
    if decoder is None:
        return None

    temp_path = ""
    try:
        with tempfile.NamedTemporaryFile("w", suffix=".pem", delete=False, encoding="ascii") as handle:
            handle.write(pem)
            temp_path = handle.name
        return decoder(temp_path)
    except Exception:
        return None
    finally:
        if temp_path:
            try:
                os.unlink(temp_path)
            except OSError:
                pass


def build_pem_certificate_summary(value: Any, label: str) -> dict[str, Any]:
    """Return non-secret certificate metadata without exposing raw PEM material."""
    pem_text = str(value or "").strip()
    properties: dict[str, Any] = {f"{label} Present": bool(pem_text)}
    if not pem_text:
        return properties

    pem_blocks = PEM_CERTIFICATE_PATTERN.findall(pem_text)
    if not pem_blocks:
        properties[f"{label} Parse Status"] = "No PEM Certificate Block Found"
        return properties

    fingerprints: list[str] = []
    subjects: list[str] = []
    issuers: list[str] = []

    for pem_block in pem_blocks:
        try:
            der_bytes = ssl.PEM_cert_to_DER_cert(pem_block)
            if isinstance(der_bytes, str):
                der_bytes = der_bytes.encode("latin1")
            fingerprints.append(hashlib.sha256(der_bytes).hexdigest().upper())
        except Exception:
            pass

        decoded = decode_pem_certificate(pem_block)
        if not decoded:
            continue
        subject = format_certificate_name(decoded.get("subject"))
        issuer = format_certificate_name(decoded.get("issuer"))
        if subject and subject not in subjects:
            subjects.append(subject)
        if issuer and issuer not in issuers:
            issuers.append(issuer)

    properties[f"{label} Count"] = len(pem_blocks)
    if fingerprints:
        properties[f"{label} SHA256 Fingerprints"] = fingerprints
    if subjects:
        properties[f"{label} Subjects"] = subjects
    if issuers:
        properties[f"{label} Issuers"] = issuers
    return properties


def parse_json_object(value: Any) -> dict[str, Any]:
    """Return a JSON object from either an API object or a JSON-encoded string."""
    if isinstance(value, dict):
        return value
    if not isinstance(value, str) or not value.strip():
        return {}
    try:
        parsed = json.loads(value)
    except (TypeError, ValueError):
        return {}
    return parsed if isinstance(parsed, dict) else {}


def pki_role_ui_label(field: str) -> str:
    if field in PKI_ROLE_UI_LABELS:
        return PKI_ROLE_UI_LABELS[field]
    return " ".join(part.capitalize() for part in field.split("_"))


def build_pki_role_ui_properties(data: dict[str, Any], role_name: str) -> dict[str, Any]:
    properties: dict[str, Any] = {}

    for field in PKI_ROLE_UI_FIELDS:
        label = pki_role_ui_label(field)

        if field == "name":
            properties[label] = role_name
            continue
        if field == "custom_ttl":
            value = data.get("not_after") or data.get("ttl")
        elif field == "no_store":
            value = not bool(data.get("no_store", False))
        elif field == "no_store_metadata":
            if "no_store_metadata" not in data:
                continue
            value = not bool(data.get("no_store_metadata", False))
        else:
            value = data.get(field)

        converted = to_graph_property_value(value)
        if converted is None:
            continue
        properties[label] = converted

    return properties


def build_pki_engine_ui_properties(protocol_configs: dict[str, dict[str, Any]] | None = None) -> dict[str, Any]:
    protocol_configs = protocol_configs or {}
    properties: dict[str, Any] = {}

    protocol_labels = {
        "acme": "ACME",
        "cmp": "CMPv2",
        "est": "EST",
        "scep": "SCEP",
    }

    for protocol, label in protocol_labels.items():
        config = protocol_configs.get(protocol) or {}
        properties[f"{label} Enabled"] = bool(config.get("enabled", False))
        policy_field = "default_directory_policy" if protocol == "acme" else "default_path_policy"
        policy_value = to_graph_property_value(config.get(policy_field))
        if policy_value not in ("", None, []):
            properties[f"{label} Default Policy"] = policy_value

    return properties


def ssh_ui_label(field: str, label_overrides: dict[str, str] | None = None) -> str:
    if label_overrides and field in label_overrides:
        return label_overrides[field]
    return " ".join(part.upper() if part.lower() in {"ttl", "cidr"} else part.capitalize() for part in field.split("_"))


def build_ssh_role_ui_properties(data: dict[str, Any], role_name: str, zero_address_enabled: bool = False) -> dict[str, Any]:
    properties: dict[str, Any] = {
        "Role Name": role_name,
        "Zero Address Enabled": zero_address_enabled,
    }

    seen_fields: set[str] = set()
    for field in SSH_ROLE_UI_LABELS:
        if field not in data:
            continue
        converted = to_graph_property_value(data.get(field))
        if converted is None:
            continue
        properties[ssh_ui_label(field, SSH_ROLE_UI_LABELS)] = converted
        seen_fields.add(field)

    for field in sorted(data):
        if field in seen_fields:
            continue
        converted = to_graph_property_value(data.get(field))
        if converted is None:
            continue
        properties[ssh_ui_label(field, SSH_ROLE_UI_LABELS)] = converted

    return properties


