def aws_role_credential_types(data: dict[str, Any]) -> list[str]:
    values = data.get("credential_types")
    if isinstance(values, list):
        normalized = [
            str(value).strip().lower()
            for value in values
            if str(value).strip()
        ]
        if normalized:
            return list(dict.fromkeys(normalized))

    value = str(data.get("credential_type") or "").strip().lower()
    if value:
        return list(dict.fromkeys(
            credential_type.strip()
            for credential_type in value.split(",")
            if credential_type.strip()
        ))
    return []


def aws_role_selection_properties(data: dict[str, Any]) -> tuple[dict[str, Any], set[str]]:
    role_arns = [
        str(value).strip()
        for value in (data.get("role_arns") or [])
        if str(value).strip()
    ]
    if not role_arns:
        return (
            {
                "requires_role_arn_selection": False,
                "role_arn_selection_mode": "not_applicable",
            },
            set(),
        )
    if len(role_arns) == 1:
        return (
            {
                "requires_role_arn_selection": False,
                "role_arn_selection_mode": "single",
                "allowed_role_arns": role_arns,
            },
            {"allowed_role_arns"},
        )
    return (
        {
            "requires_role_arn_selection": True,
            "role_arn_selection_mode": "multiple",
            "allowed_role_arns": role_arns,
        },
        {"allowed_role_arns"},
    )


def aws_root_auth_mode(root_config: dict[str, Any] | None) -> str:
    root_config = root_config or {}
    if root_config.get("access_key"):
        return "StaticCredentials"
    if root_config.get("identity_token_audience") or root_config.get("role_arn"):
        return "PluginWIF"
    if root_config:
        return "AmbientSdkChain"
    return "Unknown"


def aws_role_fetch_surfaces(data: dict[str, Any]) -> list[str]:
    # Vault's role read response does not expose the internal legacy-path restriction
    # flag, so the collector cannot prove that a role is limited to one surface.
    return ["creds", "sts"]


def aws_role_generation_effects(data: dict[str, Any]) -> list[str]:
    credential_types = set(aws_role_credential_types(data))
    effects: list[str] = []
    if not credential_types or "iam_user" in credential_types:
        effects.extend(["IAM User", "Access Keys"])
    if not credential_types or credential_types & {"assumed_role", "federation_token", "session_token"}:
        effects.append("Temporary Session Credentials")
    return list(dict.fromkeys(effects))


def aws_role_revocation_effects(data: dict[str, Any]) -> list[str]:
    credential_types = set(aws_role_credential_types(data))
    effects: list[str] = []
    if not credential_types or "iam_user" in credential_types:
        effects.extend(["Delete IAM Access Keys", "Delete IAM User"])
    if not credential_types or credential_types & {"assumed_role", "federation_token", "session_token"}:
        effects.append("Expire Temporary Session")
    return list(dict.fromkeys(effects))


def aws_static_role_write_effects(data: dict[str, Any]) -> list[str]:
    effects = ["Create Initial Access Key or Rotate Oldest Access Key"]
    if data.get("rotation_period") or data.get("rotation_schedule"):
        effects.append("Reset Rotation Schedule")
    return effects


def build_aws_engine_ui_properties(
    root_config: dict[str, Any] | None = None,
    lease_config: dict[str, Any] | None = None,
) -> dict[str, Any]:
    properties: dict[str, Any] = {}
    root_config = root_config or {}
    lease_config = lease_config or {}
    root_auth_mode = aws_root_auth_mode(root_config)

    properties["Root Auth Mode"] = root_auth_mode
    properties["Can Rotate Root"] = root_auth_mode == "StaticCredentials"

    for field in sorted(root_config):
        if field == "secret_key":
            if root_config.get(field):
                properties["Secret Key Present"] = True
            continue
        converted = to_graph_property_value(root_config.get(field))
        if converted is None:
            continue
        properties[ssh_ui_label(field, AWS_ROOT_CONFIG_UI_LABELS)] = converted

    for field in sorted(lease_config):
        converted = to_graph_property_value(lease_config.get(field))
        if converted is None:
            continue
        properties[ssh_ui_label(field, AWS_LEASE_CONFIG_UI_LABELS)] = converted

    return properties


def build_aws_role_ui_properties(data: dict[str, Any], role_name: str) -> dict[str, Any]:
    selection_properties, _ = aws_role_selection_properties(data)
    properties: dict[str, Any] = {
        "Role Name": role_name,
        "Modeled Request Surfaces": aws_role_fetch_surfaces(data),
        "Generation Effects": aws_role_generation_effects(data),
        "Surface Restriction Visibility": "Not Exposed By Read API",
        **selection_properties,
    }

    for field in sorted(data):
        converted = to_graph_property_value(data.get(field))
        if converted is None:
            continue
        properties[ssh_ui_label(field, AWS_ROLE_UI_LABELS)] = converted

    return properties


