def azure_role_generation_mode(data: dict[str, Any]) -> str:
    if data.get("application_object_id"):
        return "existing_application_secret"
    return "new_service_principal"


def azure_role_generation_effects(data: dict[str, Any]) -> list[str]:
    if azure_role_generation_mode(data) == "existing_application_secret":
        return ["Client Secret"]
    effects = ["Application", "Service Principal", "Client Secret"]
    if data.get("azure_roles"):
        effects.append("Azure Role Assignments")
    if data.get("azure_groups"):
        effects.append("Azure Group Memberships")
    return effects


def azure_role_revocation_effects(data: dict[str, Any]) -> list[str]:
    if azure_role_generation_mode(data) == "existing_application_secret":
        return ["Delete Generated Client Secret"]
    return ["Delete Service Principal", "Delete Application"]


