def gcp_secret_type(data: dict[str, Any] | None) -> str:
    value = str((data or {}).get("secret_type") or "").strip().lower()
    if value in {"access_token", "service_account_key"}:
        return value
    return "unknown"


def gcp_generation_effects(secret_type: str) -> list[str]:
    if secret_type == "access_token":
        return ["OAuth2 Access Token"]
    if secret_type == "service_account_key":
        return ["Service Account Key"]
    return ["OAuth2 Access Token", "Service Account Key"]


def gcp_revocation_effects(secret_type: str) -> list[str]:
    if secret_type == "access_token":
        return ["Expire Naturally"]
    if secret_type == "service_account_key":
        return ["Delete Service Account Key On Lease Expiry"]
    return ["Expire Naturally", "Delete Service Account Key On Lease Expiry"]


