        names = self.client.list(f"auth/{raw_path}role") or []
        for name in names:
            data = self.client.read(f"auth/{raw_path}role/{name}")
            if not data:
                continue

            node_id = self._id("auth_oci_role", accessor, name)
            token_policies = data.get("token_policies") or data.get("policies") or []
            if isinstance(token_policies, str):
                token_policies = [p.strip() for p in token_policies.split(",") if p.strip()]

            ocid_list = data.get("ocid_list") or []
            if isinstance(ocid_list, str):
                ocid_list = [ocid.strip() for ocid in ocid_list.split(",") if ocid.strip()]
            else:
                ocid_list = [str(ocid).strip() for ocid in ocid_list if str(ocid).strip()]

            alias_metadata = data.get("alias_metadata") or {}
