    def _collect_database_connections_for_engine(self, accessor: str, info: dict) -> int:
        connections = self._database_connections.setdefault(accessor, {})
        count = 0
        response = self.client.list_raw(f"{info['path']}config")
        collection_complete = response is not None

        for name in VaultClient._list_response_names(response):
            connection_name = str(name).rstrip("/")
            if not connection_name:
                continue
            connection_data = self.client.read(f"{info['path']}config/{connection_name}")
            if connection_data is None:
                collection_complete = False
            connection_info = self._build_database_connection_info(
                accessor,
                info,
                connection_name,
                connection_data or {},
                collection_complete=connection_data is not None,
            )
            connections[connection_name] = connection_info
            self.nodes.append(GraphNode(
                id=connection_info["node_id"],
                kinds=get_database_connection_kinds(),
                properties=connection_info["properties"],
            ))
            count += 1

        self._database_connection_collection_complete[accessor] = collection_complete
        return count

