    def _collect_hierarchical_resource_names(self, base_path: str) -> list[str]:
        names: set[str] = set()
        visited_prefixes: set[str] = set()

        def walk(prefix: str = ""):
            normalized_prefix = prefix.strip("/")
            if normalized_prefix in visited_prefixes:
                return
            visited_prefixes.add(normalized_prefix)

            list_path = base_path if not normalized_prefix else f"{base_path}/{normalized_prefix}"
            for entry in self.client.list(list_path):
                entry_name = str(entry).strip()
                if not entry_name:
                    continue
                combined = f"{normalized_prefix}/{entry_name}" if normalized_prefix else entry_name
                if entry_name.endswith("/"):
                    walk(combined.rstrip("/"))
                else:
                    names.add(combined.rstrip("/"))

        walk()
        return sorted(names)

    def _collect_ldap_resources(self):
        log.info("Collecting LDAP resources...")
        total_static_roles = 0
        total_dynamic_roles = 0
        total_library_sets = 0
        total_service_accounts = 0

        for accessor, info in self._secrets_engines.items():
            if info["type"] != "ldap":
                continue
            total_static_roles += self._collect_ldap_static_roles_for_engine(accessor, info)
            if self._ldap_is_self_managed(info):
                continue
            total_dynamic_roles += self._collect_ldap_dynamic_roles_for_engine(accessor, info)
            set_count, service_account_count = self._collect_ldap_library_sets_for_engine(accessor, info)
            total_library_sets += set_count
            total_service_accounts += service_account_count

        log.info(
            "  Found %d LDAP static roles, %d LDAP dynamic roles, %d LDAP library sets, and %d LDAP service accounts",
            total_static_roles,
            total_dynamic_roles,
            total_library_sets,
            total_service_accounts,
        )

    def _collect_ldap_static_roles_for_engine(self, accessor: str, info: dict) -> int:
        roles = self._ldap_static_roles.setdefault(accessor, {})
        count = 0

        for role_name in self._collect_hierarchical_resource_names(f"{info['path']}static-role"):
            role_data = self.client.read(f"{info['path']}static-role/{role_name}") or {}
            credential_data = self.client.read(f"{info['path']}static-cred/{role_name}") or {}
            role_info = self._build_ldap_static_role_info(accessor, info, role_name, role_data, credential_data)
            roles[role_name] = role_info

            self.nodes.append(GraphNode(
                id=role_info["node_id"],
                kinds=get_ldap_static_role_kinds(),
                properties=role_info["properties"],
            ))
            count += 1

        return count

    def _collect_ldap_dynamic_roles_for_engine(self, accessor: str, info: dict) -> int:
        roles = self._ldap_dynamic_roles.setdefault(accessor, {})
        count = 0

        for role_name in self._collect_hierarchical_resource_names(f"{info['path']}role"):
            role_data = self.client.read(f"{info['path']}role/{role_name}") or {}
            role_info = self._build_ldap_dynamic_role_info(accessor, info, role_name, role_data)
            roles[role_name] = role_info

            self.nodes.append(GraphNode(
                id=role_info["node_id"],
                kinds=get_ldap_dynamic_role_kinds(),
                properties=role_info["properties"],
            ))
            count += 1

        return count

    def _collect_ldap_library_sets_for_engine(self, accessor: str, info: dict) -> tuple[int, int]:
        library_sets = self._ldap_library_sets.setdefault(accessor, {})
        service_accounts = self._ldap_service_accounts.setdefault(accessor, {})
        set_count = 0
        service_account_count = 0

        for set_name in self._collect_hierarchical_resource_names(f"{info['path']}library"):
            set_data = self.client.read(f"{info['path']}library/{set_name}") or {}
            status_data = self.client.read(f"{info['path']}library/{set_name}/status") or {}
            set_info = self._build_ldap_library_set_info(accessor, info, set_name, set_data)
            library_sets[set_name] = set_info

            self.nodes.append(GraphNode(
                id=set_info["node_id"],
                kinds=get_ldap_library_set_kinds(),
                properties=set_info["properties"],
            ))
            set_count += 1

            for account_name in set_data.get("service_account_names") or []:
                account_name = str(account_name).strip()
                if not account_name:
                    continue
                status = status_data.get(account_name) if isinstance(status_data, dict) else None
                service_account_info = self._build_ldap_service_account_info(
                    accessor,
                    info,
                    set_name,
                    set_info["node_id"],
                    account_name,
                    status if isinstance(status, dict) else {},
                )
                service_accounts[f"{set_name}:{account_name}"] = service_account_info
                self.nodes.append(GraphNode(
                    id=service_account_info["node_id"],
                    kinds=get_ldap_service_account_kinds(),
                    properties=service_account_info["properties"],
                ))
                service_account_count += 1

        return set_count, service_account_count

