    def _compute_auth_spiffe_match_edges(self):
        """Connect existing SPIFFE aliases to roles whose workload patterns may select them."""
        for entity_data in self._entity_by_id.values():
            for alias in entity_data.get("aliases") or []:
                accessor = str(alias.get("mount_accessor") or "")
                auth_info = self._auth_methods.get(accessor)
                if not auth_info or auth_info.get("type") != "spiffe":
                    continue

                alias_node_id = self._entity_alias_nodes.get(str(alias.get("id") or ""))
                if not alias_node_id:
                    continue

                spiffe_config = auth_info.get("spiffe_config") or {}
                workload_id = spiffe_workload_id_from_alias(
                    alias.get("name", ""),
                    spiffe_config.get("trust_domain", ""),
                )
                if workload_id is None:
                    continue

                for role in self._auth_spiffe_roles.get(accessor, {}).values():
                    matched_patterns = [
                        pattern
                        for pattern in role.get("workload_id_patterns") or []
                        if spiffe_workload_pattern_matches(pattern, workload_id)
                    ]
                    if not matched_patterns:
                        continue

                    self._emit_or_merge_edge(
                        alias_node_id,
                        role["node_id"],
                        "Vault_AuthSpiffeMayMatchRole",
                        properties={
                            "workload_id": workload_id,
                            "matched_patterns": matched_patterns,
                            "match_types": list(dict.fromkeys(
                                spiffe_workload_pattern_match_type(pattern)
                                for pattern in matched_patterns
                            )),
                        },
                        array_property_keys={"matched_patterns", "match_types"},
                    )

