    def _compute_database_resource_edges(self):
        """Database containment and role-to-connection reference edges."""
        for resource_map in (
            self._database_connections,
            self._database_roles,
            self._database_static_roles,
        ):
            for accessor, resources in resource_map.items():
                engine = self._secrets_engines.get(accessor)
                if not engine:
                    continue
                for resource in resources.values():
                    self.edges.append(GraphEdge(
                        source=engine["node_id"],
                        target=resource["node_id"],
                        kind="Vault_DatabaseContains",
                    ))

        for resource_map in (self._database_roles, self._database_static_roles):
            for accessor, roles in resource_map.items():
                engine = self._secrets_engines.get(accessor)
                if not engine:
                    continue
                for role in roles.values():
                    connection_name = role.get("connection_name", "")
                    if not connection_name:
                        continue
                    connection = self._database_connections.get(accessor, {}).get(connection_name)
                    if not connection:
                        connection = self._ensure_database_connection(accessor, engine, connection_name)
                    reference_properties, reference_array_keys = self._database_role_connection_reference_properties(
                        connection,
                        role,
                    )
                    self._emit_or_merge_edge(
                        role["node_id"],
                        connection["node_id"],
                        "Vault_References",
                        properties={
                            "reference_types": ["Database Connection"],
                            "reference_evidence": ["Role Connection Assignment"],
                            **reference_properties,
                        },
                        array_property_keys={
                            "reference_types",
                            "reference_evidence",
                            *reference_array_keys,
                        },
                    )

