    @staticmethod
    def _pki_scep_expected_auth_type(scep_config: dict[str, Any]) -> str:
        external_validation = scep_config.get("external_validation") or {}
        if isinstance(external_validation, dict) and "intune" in external_validation:
            return "intune"
        return "static-challenge"

    @staticmethod
    def _pki_scep_role_match_status(role_auth_type: str, expected_auth_type: str) -> str:
        if not role_auth_type:
            return "Unknown"
        return "Compatible" if role_auth_type == expected_auth_type else "Incompatible"

    @staticmethod
    def _pki_delegated_auth_is_allowed(engine: dict[str, Any], auth_accessor: str) -> bool:
        return auth_accessor in set(normalize_string_list(engine.get("delegated_auth_accessors")))

    @staticmethod
    def _pki_protocol_label(protocol: str) -> str:
        return {
            "cmp": "CMPv2",
            "est": "EST",
            "scep": "SCEP",
        }.get(protocol, protocol.upper())

    def _compute_pki_scep_auth_edges(
        self,
        engine: dict[str, Any],
        scep_authenticator: dict[str, Any],
        expected_auth_type: str,
    ):
        auth_accessor = str(scep_authenticator.get("accessor") or "").strip()
        if not auth_accessor or not self._pki_delegated_auth_is_allowed(engine, auth_accessor):
            return

        auth_info = self._auth_methods.get(auth_accessor)
        if not auth_info or auth_info.get("type") != "scep":
            return

        scep_role_name = str(scep_authenticator.get("scep_role") or "").strip()
        properties: dict[str, Any] = {
            "reference_types": ["Delegated Authentication"],
            "reference_evidence": ["PKI SCEP Authenticator Configuration"],
            "Authenticator Type": "SCEP",
            "Delegated Auth Accessor": auth_accessor,
            "Delegation Allowed": True,
            "SCEP Enabled": True,
            "Expected Authentication Type": expected_auth_type,
            "Role Selections": ["Explicit Role" if scep_role_name else "First Matching Role"],
        }

        role: dict[str, Any] | None = None
        if scep_role_name:
            role = self._auth_scep_roles.get(auth_accessor, {}).get(scep_role_name)
            if not role:
                role = self._ensure_auth_scep_role(auth_accessor, scep_role_name)
            role_auth_type = str(role.get("auth_type") or "")
            properties["Selected Auth Roles"] = [scep_role_name]
            properties["Role Match Status"] = self._pki_scep_role_match_status(role_auth_type, expected_auth_type)
            if role_auth_type:
                properties["Role Authentication Type"] = role_auth_type

        self._emit_or_merge_edge(
            engine["node_id"],
            auth_info["node_id"],
            "Vault_References",
            properties=properties,
            array_property_keys={
                "reference_types", "reference_evidence", "Role Selections",
                "Selected Auth Roles",
            },
        )

        if role:
            role_properties = {
                **properties,
                "reference_types": ["Explicit Delegated Authentication Role"],
                "reference_evidence": ["PKI SCEP scep_role Configuration"],
            }
            self._emit_or_merge_edge(
                engine["node_id"],
                role["node_id"],
                "Vault_References",
                properties=role_properties,
                array_property_keys={
                    "reference_types", "reference_evidence", "Role Selections",
                    "Selected Auth Roles",
                },
            )

    def _compute_pki_tls_cert_auth_edges(
        self,
        engine: dict[str, Any],
        cert_authenticator: dict[str, Any],
        protocol: str,
    ):
        auth_accessor = str(cert_authenticator.get("accessor") or "").strip()
        if not auth_accessor or not self._pki_delegated_auth_is_allowed(engine, auth_accessor):
            return

        auth_info = self._auth_methods.get(auth_accessor)
        if not auth_info or auth_info.get("type") != "cert":
            return

        cert_role_name = str(cert_authenticator.get("cert_role") or "").strip()
        protocol_label = self._pki_protocol_label(protocol)
        auth_properties: dict[str, Any] = {
            "reference_types": ["Delegated Authentication"],
            "reference_evidence": [f"PKI {protocol_label} Authenticator Configuration"],
            "Authenticator Type": "TLS Certificate",
            "Delegated Auth Accessor": auth_accessor,
            "Delegation Allowed": True,
            "Protocols": [protocol_label],
            f"{protocol_label} Enabled": True,
            "Role Selections": ["Explicit Role" if cert_role_name else "First Matching Role"],
        }
        role_properties = {**auth_properties}
        if cert_role_name:
            auth_properties["Selected Auth Roles"] = [cert_role_name]
            role_properties["Selected Auth Roles"] = [cert_role_name]

        self._emit_or_merge_edge(
            engine["node_id"],
            auth_info["node_id"],
            "Vault_References",
            properties=auth_properties,
            array_property_keys={
                "Protocols", "reference_types", "reference_evidence", "Role Selections",
                "Selected Auth Roles",
            },
        )

        if cert_role_name:
            role = self._auth_cert_roles.get(auth_accessor, {}).get(cert_role_name.lower())
            if not role:
                role = self._ensure_auth_cert_role(auth_accessor, cert_role_name)
            role_properties["reference_types"] = ["Explicit Delegated Authentication Role"]
            role_properties["reference_evidence"] = [
                f"PKI {protocol_label} cert_role Configuration"
            ]
            self._emit_or_merge_edge(
                engine["node_id"],
                role["node_id"],
                "Vault_References",
                properties=role_properties,
                array_property_keys={
                    "Protocols", "reference_types", "reference_evidence", "Role Selections",
                    "Selected Auth Roles",
                },
            )

    def _compute_pki_userpass_auth_edges(
        self,
        engine: dict[str, Any],
        userpass_authenticator: dict[str, Any],
        protocol: str,
    ):
        auth_accessor = str(userpass_authenticator.get("accessor") or "").strip()
        if not auth_accessor or not self._pki_delegated_auth_is_allowed(engine, auth_accessor):
            return

        auth_info = self._auth_methods.get(auth_accessor)
        if not auth_info or auth_info.get("type") != "userpass":
            return

        protocol_label = self._pki_protocol_label(protocol)
        self._emit_or_merge_edge(
            engine["node_id"],
            auth_info["node_id"],
            "Vault_References",
            properties={
                "reference_types": ["Delegated Authentication"],
                "reference_evidence": [f"PKI {protocol_label} Authenticator Configuration"],
                "Authenticator Type": "UserPass",
                "Delegated Auth Accessor": auth_accessor,
                "Delegation Allowed": True,
                "Protocols": [protocol_label],
                f"{protocol_label} Enabled": True,
            },
            array_property_keys={"Protocols", "reference_types", "reference_evidence"},
        )

    def _compute_pki_resource_edges(self):
        """PKI containment edges for roles, issuers, and keys."""
        for accessor, roles in self._pki_roles.items():
            engine = self._secrets_engines.get(accessor)
            if not engine:
                continue
            for role in roles.values():
                self.edges.append(GraphEdge(
                    source=engine["node_id"],
                    target=role["node_id"],
                    kind="Vault_PkiContainsRole",
                ))

        for accessor, issuers in self._pki_issuers.items():
            engine = self._secrets_engines.get(accessor)
            if not engine:
                continue
            for issuer in issuers.values():
                self.edges.append(GraphEdge(
                    source=engine["node_id"],
                    target=issuer["node_id"],
                    kind="Vault_PkiContainsIssuer",
                ))

        for accessor, keys in self._pki_keys.items():
            engine = self._secrets_engines.get(accessor)
            if not engine:
                continue
            for key in keys.values():
                self.edges.append(GraphEdge(
                    source=engine["node_id"],
                    target=key["node_id"],
                    kind="Vault_PkiContainsKey",
                ))

        for accessor, issuers in self._pki_issuers.items():
            keys = self._pki_keys.get(accessor, {})
            for issuer in issuers.values():
                key_ref = issuer.get("key_ref", "")
                if not key_ref:
                    continue
                for key in keys.values():
                    if key_ref in key.get("aliases", set()):
                        self._emit_or_merge_edge(
                            issuer["node_id"],
                            key["node_id"],
                            "Vault_References",
                            properties={
                                "reference_types": ["Signing Key"],
                                "reference_evidence": ["Issuer Key Reference"],
                                "key_references": [key_ref],
                            },
                            array_property_keys={
                                "reference_types", "reference_evidence", "key_references",
                            },
                        )
                        break

        for keys in self._pki_keys.values():
            for key in keys.values():
                managed_key = self._resolve_managed_key_reference(key)
                if managed_key:
                    self.edges.append(GraphEdge(
                        source=key["node_id"],
                        target=managed_key["node_id"],
                        kind="Vault_ManagedBy",
                        properties={"reference_evidence": ["PKI Key Configuration"]},
                    ))
                    self._update_node_properties(
                        key["node_id"],
                        {"External Crypto Backend": managed_key.get("backend_type", "")},
                    )

        for accessor, issuers in self._pki_issuers.items():
            keys = self._pki_keys.get(accessor, {})
            for issuer in issuers.values():
                managed_key = self._resolve_managed_key_reference(issuer)
                if not managed_key:
                    continue
                source_node_id = issuer["node_id"]
                key_ref = issuer.get("key_ref", "")
                for key in keys.values():
                    if key_ref and key_ref in key.get("aliases", set()):
                        source_node_id = key["node_id"]
                        break
                if not any(
                    edge.source == source_node_id
                    and edge.target == managed_key["node_id"]
                    and edge.kind == "Vault_ManagedBy"
                    for edge in self.edges
                ):
                    self.edges.append(GraphEdge(
                        source=source_node_id,
                        target=managed_key["node_id"],
                        kind="Vault_ManagedBy",
                        properties={"reference_evidence": ["PKI Issuer Configuration"]},
                    ))
                self._update_node_properties(
                    source_node_id,
                    {"External Crypto Backend": managed_key.get("backend_type", "")},
                )

        for accessor, engine in self._secrets_engines.items():
            if engine.get("type") != "pki":
                continue

            protocol_configs = engine.get("pki_protocol_configs") or {}
            for protocol in ("cmp", "est", "scep"):
                config = protocol_configs.get(protocol) or {}
                if not isinstance(config, dict) or not bool(config.get("enabled", False)):
                    continue
                authenticators = config.get("authenticators") or {}
                if not isinstance(authenticators, dict):
                    continue

                if protocol == "scep":
                    expected_auth_type = self._pki_scep_expected_auth_type(config)
                    scep_authenticator = authenticators.get("scep") or {}
                    if isinstance(scep_authenticator, dict):
                        self._compute_pki_scep_auth_edges(engine, scep_authenticator, expected_auth_type)

                cert_authenticator = authenticators.get("cert") or {}
                if isinstance(cert_authenticator, dict):
                    self._compute_pki_tls_cert_auth_edges(engine, cert_authenticator, protocol)

                if protocol == "est":
                    userpass_authenticator = authenticators.get("userpass") or {}
                    if isinstance(userpass_authenticator, dict):
                        self._compute_pki_userpass_auth_edges(engine, userpass_authenticator, protocol)

    def _compute_oidc_edges(self):
        """OIDC assignment/provider/client edges."""
        # Build client_id -> node_id lookup
        client_id_to_node = {}
        client_name_to_node = {}
        for name, info in self._oidc_clients.items():
            cid = info.get("client_id", "")
            node_id = info["node_id"]
            client_id_to_node[cid] = node_id
            client_name_to_node[name] = node_id

        # OidcAllowsApplication: Provider -> Application
        for pname, pinfo in self._oidc_providers.items():
            allowed = pinfo.get("allowed_client_ids") or []
            if pname == "default" and "*" not in allowed:
                allowed = [*allowed, "*"]
            if "*" in allowed:
                # Wildcard: all clients
                for cname, cinfo in self._oidc_clients.items():
                    self.edges.append(GraphEdge(
                        source=pinfo["node_id"],
                        target=cinfo["node_id"],
                        kind="Vault_OidcAllowsApplication",
                    ))
            else:
                for cid in allowed:
                    if cid in client_id_to_node:
                        self.edges.append(GraphEdge(
                            source=pinfo["node_id"],
                            target=client_id_to_node[cid],
                            kind="Vault_OidcAllowsApplication",
                        ))

        # OidcGrantsAccess: Assignment -> Client
        for aname, ainfo in self._oidc_assignments.items():
            # Find which clients reference this assignment
            for cname, cinfo in self._oidc_clients.items():
                if aname in (cinfo.get("assignments") or []):
                    self.edges.append(GraphEdge(
                        source=ainfo["node_id"],
                        target=cinfo["node_id"],
                        kind="Vault_OidcGrantsAccess",
                    ))

        # OIDC applications reference the key used to sign their tokens.
        for cname, cinfo in self._oidc_clients.items():
            key_name = cinfo.get("key") or "default"
            key_info = self._oidc_keys.get(key_name)
            if key_info:
                self._emit_or_merge_edge(
                    cinfo["node_id"],
                    key_info["node_id"],
                    "Vault_References",
                    properties={
                        "reference_types": ["OIDC Signing Key"],
                        "reference_evidence": ["OIDC Application Key"],
                        "key_references": [key_name],
                    },
                    array_property_keys={
                        "reference_types", "reference_evidence", "key_references",
                    },
                )

        # OidcSupportsScope: Provider -> Scope
        for pinfo in self._oidc_providers.values():
            scope_names = list(dict.fromkeys([*(pinfo.get("scopes_supported") or []), "openid"]))
            for scope_name in scope_names:
                scope_info = self._oidc_scopes.get(scope_name)
                if scope_info:
                    self.edges.append(GraphEdge(
                        source=pinfo["node_id"],
                        target=scope_info["node_id"],
                        kind="Vault_OidcSupportsScope",
                    ))

        # OidcAssignedTo: Entity/Group -> Assignment
        for aname, ainfo in self._oidc_assignments.items():
            entity_ids = ainfo.get("entity_ids") or []
            group_ids = ainfo.get("group_ids") or []
            if aname == "allow_all" and "*" not in entity_ids:
                entity_ids = [*entity_ids, "*"]

            for eid in entity_ids:
                if eid == "*":
                    # Wildcard: all entities
                    for e_id in self._entity_by_id:
                        self.edges.append(GraphEdge(
                            source=self._id("entity", e_id),
                            target=ainfo["node_id"],
                            kind="Vault_OidcAssignedTo",
                        ))
                elif eid in self._entity_by_id:
                    self.edges.append(GraphEdge(
                        source=self._id("entity", eid),
                        target=ainfo["node_id"],
                        kind="Vault_OidcAssignedTo",
                    ))

            for gid in group_ids:
                if gid == "*":
                    # Wildcard: all groups
                    for g_id in self._group_by_id:
                        self.edges.append(GraphEdge(
                            source=self._id("group", g_id),
                            target=ainfo["node_id"],
                            kind="Vault_OidcAssignedTo",
                        ))
                elif gid in self._group_by_id:
                    self.edges.append(GraphEdge(
                        source=self._id("group", gid),
                        target=ainfo["node_id"],
                        kind="Vault_OidcAssignedTo",
                    ))

        # Identity token roles use named OIDC signing keys independently of provider clients.
        for role in self._oidc_token_roles.values():
            key_name = str(role.get("key") or "default")
            key_info = self._oidc_keys.get(key_name)
            if key_info:
                self._emit_or_merge_edge(
                    role["node_id"],
                    key_info["node_id"],
                    "Vault_References",
                    properties={
                        "reference_types": ["OIDC Signing Key"],
                        "reference_evidence": ["OIDC Token Role Key"],
                        "key_references": [key_name],
                    },
                    array_property_keys={
                        "reference_types", "reference_evidence", "key_references",
                    },
                )

    def _compute_mfa_edges(self):
        """Model login MFA as a constraint layer, not as a traversable auth path."""
        for enforcement in self._mfa_login_enforcements.values():
            enforcement_node = enforcement["node_id"]
            for method_id in enforcement.get("mfa_method_ids") or []:
                method = self._mfa_methods.get(str(method_id))
                if method:
                    self.edges.append(GraphEdge(
                        source=enforcement_node,
                        target=method["node_id"],
                        kind="Vault_MfaUsesMethod",
                    ))

            unresolved_entity_ids: list[str] = []
            for entity_id in enforcement.get("identity_entity_ids") or []:
                normalized_entity_id = str(entity_id)
                if normalized_entity_id in self._entity_by_id:
                    self._emit_or_merge_edge(
                        enforcement_node,
                        self._id("entity", normalized_entity_id),
                        "Vault_MfaAppliesTo",
                        properties={"selector_types": ["Entity"]},
                        array_property_keys={"selector_types"},
                    )
                else:
                    self._append_unique(unresolved_entity_ids, normalized_entity_id)

            unresolved_group_ids: list[str] = []
            for group_id in enforcement.get("identity_group_ids") or []:
                normalized_group_id = str(group_id)
                if normalized_group_id in self._group_by_id:
                    self._emit_or_merge_edge(
                        enforcement_node,
                        self._id("group", normalized_group_id),
                        "Vault_MfaAppliesTo",
                        properties={"selector_types": ["Group"]},
                        array_property_keys={"selector_types"},
                    )
                else:
                    self._append_unique(unresolved_group_ids, normalized_group_id)

            unresolved_selector_properties: dict[str, Any] = {}
            if unresolved_entity_ids:
                unresolved_selector_properties["Unresolved Identity Entity IDs"] = unresolved_entity_ids
            if unresolved_group_ids:
                unresolved_selector_properties["Unresolved Identity Group IDs"] = unresolved_group_ids
            if unresolved_selector_properties:
                self._update_node_properties(enforcement_node, unresolved_selector_properties)

            for accessor in enforcement.get("auth_method_accessors") or []:
                auth_method = self._auth_methods.get(str(accessor))
                if auth_method:
                    self._emit_or_merge_edge(
                        enforcement_node,
                        auth_method["node_id"],
                        "Vault_MfaAppliesTo",
                        properties={"selector_types": ["Auth Method Accessor"]},
                        array_property_keys={"selector_types"},
                    )

            for auth_type in enforcement.get("auth_method_types") or []:
                for auth_method in self._auth_methods.values():
                    if auth_method.get("type") != auth_type:
                        continue
                    self._emit_or_merge_edge(
                        enforcement_node,
                        auth_method["node_id"],
                        "Vault_MfaAppliesTo",
                        properties={"selector_types": ["Auth Method Type"]},
                        array_property_keys={"selector_types"},
                    )

    def _compute_scim_edges(self):
        """Model SCIM client registrations and the entity that can act as each client."""
        for client in self._scim_clients.values():
            principal_id = str(client.get("access_grant_principal") or "")
            if principal_id in self._entity_by_id:
                self.edges.append(GraphEdge(
                    source=client["node_id"],
                    target=self._id("entity", principal_id),
                    kind="Vault_ScimUsesPrincipal",
                ))

            client_id = str(client.get("client_id") or "")
            if not client_id:
                continue
            for entity_id, entity in self._entity_by_id.items():
                if str(entity.get("scim_client_id") or "") == client_id:
                    self.edges.append(GraphEdge(
                        source=client["node_id"],
                        target=self._id("entity", entity_id),
                        kind="Vault_ScimManages",
                    ))
            for group_id, group in self._group_by_id.items():
                if str(group.get("scim_client_id") or "") == client_id:
                    self.edges.append(GraphEdge(
                        source=client["node_id"],
                        target=self._id("group", group_id),
                        kind="Vault_ScimManages",
                    ))

    def _iter_pki_roles(self, accessor: str) -> list[dict[str, Any]]:
        return sorted(
            self._pki_roles.get(accessor, {}).values(),
            key=lambda role: role["name"],
        )

    def _iter_pki_issuers(self, accessor: str) -> list[dict[str, Any]]:
        return sorted(
            self._pki_issuers.get(accessor, {}).values(),
            key=lambda issuer: issuer["name"],
        )

    def _iter_pki_keys(self, accessor: str) -> list[dict[str, Any]]:
        return sorted(
            self._pki_keys.get(accessor, {}).values(),
            key=lambda key: key["name"],
        )

    @staticmethod
    def _pki_is_globbed(segment: str) -> bool:
        return bool(segment) and (segment in {"*", "+"} or "*" in segment)

    @staticmethod
    def _pki_alias_matches(pattern: str, aliases: set[str]) -> bool:
        return any(
            policy_path_matches_resource_path(pattern, alias)
            for alias in aliases
            if alias
        )

    def _match_pki_roles(self, accessor: str, pattern: str) -> list[dict[str, Any]]:
        return [
            role for role in self._iter_pki_roles(accessor)
            if policy_path_matches_resource_path(pattern, role["name"])
        ]

    def _match_pki_issuers(self, accessor: str, pattern: str) -> list[dict[str, Any]]:
        return [
            issuer for issuer in self._iter_pki_issuers(accessor)
            if self._pki_alias_matches(pattern, issuer.get("aliases", set()))
        ]

    def _match_pki_keys(self, accessor: str, pattern: str) -> list[dict[str, Any]]:
        return [
            key for key in self._iter_pki_keys(accessor)
            if self._pki_alias_matches(pattern, key.get("aliases", set()))
        ]

    def _iter_aws_roles(self, accessor: str) -> list[dict[str, Any]]:
        return sorted(
            self._aws_roles.get(accessor, {}).values(),
            key=lambda role: role["name"],
        )

    def _match_aws_roles(self, accessor: str, pattern: str) -> list[dict[str, Any]]:
        return [
            role for role in self._iter_aws_roles(accessor)
            if policy_path_matches_resource_path(pattern, role["name"])
        ]

    def _ensure_aws_role(
        self,
        accessor: str,
        info: dict,
        role_name: str,
    ) -> dict[str, Any]:
        roles = self._aws_roles.setdefault(accessor, {})
        if role_name in roles:
            return roles[role_name]

        role_info = self._build_aws_role_info(accessor, info, role_name, {}, synthetic=True)
        roles[role_name] = role_info
        self.nodes.append(GraphNode(
            id=role_info["node_id"],
            kinds=get_aws_role_kinds(),
            properties=role_info["properties"],
        ))
        self.edges.append(GraphEdge(
            source=info["node_id"],
            target=role_info["node_id"],
            kind="Vault_AwsContainsRole",
        ))
        return role_info

    def _iter_aws_static_roles(self, accessor: str) -> list[dict[str, Any]]:
        return sorted(
            self._aws_static_roles.get(accessor, {}).values(),
            key=lambda role: role["name"],
        )

    def _match_aws_static_roles(self, accessor: str, pattern: str) -> list[dict[str, Any]]:
        return [
            role for role in self._iter_aws_static_roles(accessor)
            if policy_path_matches_resource_path(pattern, role["name"])
        ]

    def _ensure_aws_static_role(
        self,
        accessor: str,
        info: dict,
        role_name: str,
    ) -> dict[str, Any]:
        roles = self._aws_static_roles.setdefault(accessor, {})
        if role_name in roles:
            return roles[role_name]

        role_info = self._build_aws_static_role_info(accessor, info, role_name, {}, {}, synthetic=True)
        roles[role_name] = role_info
        self.nodes.append(GraphNode(
            id=role_info["node_id"],
            kinds=get_aws_static_role_kinds(),
            properties=role_info["properties"],
        ))
        self.edges.append(GraphEdge(
            source=info["node_id"],
            target=role_info["node_id"],
            kind="Vault_AwsContainsStaticRole",
        ))
        return role_info

    @staticmethod
    def _aws_role_credential_types(role: dict[str, Any]) -> list[str]:
        values = role.get("properties", {}).get("Credential Types")
        if isinstance(values, list):
            normalized = [
                str(value).strip().lower()
                for value in values
                if str(value).strip()
            ]
            if normalized:
                return list(dict.fromkeys(normalized))

        value = str(role.get("properties", {}).get("Credential Type") or "").strip().lower()
        if value:
            return list(dict.fromkeys(
                credential_type.strip()
                for credential_type in value.split(",")
                if credential_type.strip()
            ))
        return []

    @staticmethod
    def _aws_role_arn_selection_properties(role: dict[str, Any]) -> tuple[dict[str, Any], set[str]]:
        role_arns = [
            str(value).strip()
            for value in (role.get("properties", {}).get("Role ARNs") or [])
            if str(value).strip()
        ]
        if not role_arns:
            return (
                {
                    "requires_role_arn_selection": False,
                    "role_arn_selection_mode": "not_applicable",
                },
                set(),
            )
        if len(role_arns) == 1:
            return (
                {
                    "requires_role_arn_selection": False,
                    "role_arn_selection_mode": "single",
                    "allowed_role_arns": role_arns,
                },
                {"allowed_role_arns"},
            )
        return (
            {
                "requires_role_arn_selection": True,
                "role_arn_selection_mode": "multiple",
                "allowed_role_arns": role_arns,
            },
            {"allowed_role_arns"},
        )

    @staticmethod
    def _aws_static_role_write_effects(role: dict[str, Any]) -> list[str]:
        effects = ["Create Initial Access Key or Rotate Oldest Access Key"]
        properties = role.get("properties", {})
        if properties.get("Rotation Period") or properties.get("Rotation Schedule"):
            effects.append("Reset Rotation Schedule")
        return effects

    @staticmethod
    def _aws_manage_operations(caps: list[str], include_delete: bool = True) -> list[str]:
        operations: list[str] = []
        if any(cap in caps for cap in ("create", "update")):
            operations.append("write")
        if include_delete and "delete" in caps:
            operations.append("delete")
        return operations

    @staticmethod
    def _aws_role_manage_operations(caps: list[str]) -> list[str]:
        operations: list[str] = []
        if "update" in caps:
            operations.append("write")
        if "delete" in caps:
            operations.append("delete")
        return operations

    @staticmethod
    def _aws_credential_mode_viability(
        role: dict[str, Any],
    ) -> tuple[list[str], list[str], list[str]]:
        credential_types = VaultCollector._aws_role_credential_types(role) or [
            "iam_user",
            "assumed_role",
            "federation_token",
            "session_token",
        ]
        if role.get("synthetic") or role.get("collection_complete", True) is False:
            return [], credential_types, ["Target AWS Role Configuration Must Be Collected"]

        conditional_types: list[str] = []
        requirements: list[str] = []
        if (
            "session_token" in credential_types
            and bool(role.get("properties", {}).get("MFA Serial Number"))
        ):
            conditional_types.append("session_token")
            requirements.append("Session Token Credentials Require An MFA Code")

        viable_types = [
            credential_type
            for credential_type in credential_types
            if credential_type not in conditional_types
        ]
        return viable_types, conditional_types, requirements

    @staticmethod
    def _aws_credential_request_properties(
        role: dict[str, Any] | None,
        surface: str,
        credential_types: list[str] | None = None,
    ) -> tuple[dict[str, Any], set[str]]:
        properties: dict[str, Any] = {
            "request_surface": surface,
            "request_method": "GET" if surface == "creds" else "POST",
            "lease_bound": True,
        }
        array_property_keys = {
            "credential_types",
            "generation_effects",
            "revocation_effects",
            "modes",
            "requirements",
        }

        if role is None:
            credential_types = ["iam_user", "assumed_role", "federation_token", "session_token"]
            properties.update({
                "credential_types": credential_types,
                "generation_effects": aws_role_generation_effects({"credential_types": credential_types}),
                "revocation_effects": aws_role_revocation_effects({"credential_types": credential_types}),
                "modes": list(AWS_CREDENTIAL_MODE_LABELS.values()),
                "requirements": ["Generate Credentials: Target Role Configuration Must Permit The Credential Type"],
            })
            return properties, array_property_keys

        credential_types = credential_types or VaultCollector._aws_role_credential_types(role) or [
            "iam_user", "assumed_role", "federation_token", "session_token",
        ]
        properties["credential_types"] = credential_types
        properties["modes"] = [
            AWS_CREDENTIAL_MODE_LABELS[credential_type]
            for credential_type in credential_types
            if credential_type in AWS_CREDENTIAL_MODE_LABELS
        ]
        properties["generation_effects"] = aws_role_generation_effects({
            "credential_types": credential_types,
        })
        properties["revocation_effects"] = aws_role_revocation_effects({
            "credential_types": credential_types,
        })

        if role.get("properties", {}).get("Synthetic"):
            properties["modes"] = []
            properties["requirements"] = ["Generate Credentials: Target Role Must Exist"]
            return properties, array_property_keys

        selection_properties, selection_array_keys = VaultCollector._aws_role_arn_selection_properties(role)
        properties.update(selection_properties)
        array_property_keys.update(selection_array_keys)

        sts_credential_types = {"assumed_role", "federation_token", "session_token"}
        properties["supports_custom_ttl"] = bool(set(credential_types) & sts_credential_types)
        properties["supports_role_session_name"] = "assumed_role" in credential_types
        requirements: list[str] = []
        if properties.get("requires_role_arn_selection"):
            requirements.append("Assumed Role Credentials: Role ARN Selection Required")
        if requirements:
            properties["requirements"] = requirements
        properties.pop("requires_role_arn_selection", None)
        properties.pop("role_arn_selection_mode", None)
        return properties, array_property_keys

    @staticmethod
    def _aws_edge_capabilities(edge_kind: str, caps: list[str]) -> list[str]:
        if edge_kind in {"Vault_AwsListRoles", "Vault_AwsListStaticRoles"}:
            return filter_capabilities(caps, {"list"})
        if edge_kind in {
            "Vault_AwsReadRootConfig",
            "Vault_AwsReadLeaseConfig",
            "Vault_AwsReadRole",
            "Vault_AwsGenerateCredentials",
            "Vault_AwsReadStaticRole",
            "Vault_AwsGetStaticCredentials",
        }:
            return filter_capabilities(caps, {"read"})
        if edge_kind in {
            "Vault_AwsManageRootConfig",
            "Vault_AwsManageStaticRole",
        }:
            if edge_kind == "Vault_AwsManageRootConfig":
                return filter_capabilities(caps, {"create", "update"})
            return filter_capabilities(caps, {"create", "update", "delete"})
        if edge_kind == "Vault_AwsManageRole":
            return filter_capabilities(caps, {"update", "delete"})
        if edge_kind == "Vault_AwsManageLeaseConfig":
            return filter_capabilities(caps, {"create", "update"})
        if edge_kind in {
            "Vault_AwsRotateRoot",
            "Vault_AwsGenerateStsCredentials",
        }:
            return filter_capabilities(caps, {"create", "update"})
        return filter_capabilities(caps, {"create", "update", "delete", "read", "list"})

    def _emit_aws_edge(
        self,
        source: str,
        target: str,
        kind: str,
        caps: list[str],
        matched_path: str,
        matched_policy_path: str | None = None,
        extra_properties: dict[str, Any] | None = None,
        array_property_keys: set[str] | None = None,
        capability_kind: str | None = None,
    ):
        evidence_kind = capability_kind or kind
        edge_caps = self._aws_edge_capabilities(evidence_kind, caps)
        if not edge_caps:
            return

        properties: dict[str, Any] = {
            "capabilities": edge_caps,
            "matched_paths": [matched_path],
            "matched_policy_paths": [matched_policy_path or matched_path],
        }
        merged_array_property_keys = {"matched_paths", "matched_policy_paths"} | set(array_property_keys or set())
        config_target = AWS_CONFIG_EDGE_TARGETS.get(kind)
        if config_target:
            properties["config_targets"] = [config_target]
            merged_array_property_keys.add("config_targets")
        if kind == "Vault_AwsRotateRoot":
            properties["operations"] = ["rotate_root"]
            merged_array_property_keys.add("operations")
        if extra_properties:
            properties.update(extra_properties)

        if evidence_kind != kind:
            properties = canonical_edge_properties(evidence_kind, properties)
            merged_array_property_keys.update(canonical_edge_array_property_keys(evidence_kind))

        self._emit_or_merge_edge(
            source,
            target,
            kind,
            properties=properties,
            array_property_keys=merged_array_property_keys,
        )

    def _emit_aws_role_targets(
        self,
        policy_node: str,
        info: dict,
        role_pattern: str,
        edge_kind: str,
        caps: list[str],
        matched_path: str,
        matched_policy_path: str,
        create_synthetic_if_missing: bool = False,
        extra_properties: dict[str, Any] | None = None,
        array_property_keys: set[str] | None = None,
    ):
        matched_roles = self._match_aws_roles(info["accessor"], role_pattern)
        if not matched_roles and create_synthetic_if_missing and not self._pki_is_globbed(role_pattern):
            matched_roles = [self._ensure_aws_role(info["accessor"], info, role_pattern)]

        for role in matched_roles:
            merged_extra_properties = dict(extra_properties or {})
            merged_array_property_keys = set(array_property_keys or set())
            if edge_kind in {"Vault_AwsGenerateCredentials", "Vault_AwsGenerateStsCredentials"}:
                surface = "creds" if edge_kind == "Vault_AwsGenerateCredentials" else "sts"
                viable_types, conditional_types, requirements = self._aws_credential_mode_viability(role)

                if viable_types:
                    request_properties, request_array_keys = self._aws_credential_request_properties(
                        role,
                        surface,
                        credential_types=viable_types,
                    )
                    request_properties["prerequisite_status"] = "Viable"
                    self._emit_aws_edge(
                        policy_node,
                        role["node_id"],
                        edge_kind,
                        caps,
                        matched_path,
                        matched_policy_path,
                        extra_properties={**merged_extra_properties, **request_properties},
                        array_property_keys=merged_array_property_keys | request_array_keys,
                    )

                if conditional_types:
                    request_properties, request_array_keys = self._aws_credential_request_properties(
                        role,
                        surface,
                        credential_types=conditional_types,
                    )
                    request_properties.update({
                        "prerequisite_status": "Unknown",
                        "requirements": requirements,
                        "potential_outcomes": ["Generate AWS Credentials"],
                        "potential_only": True,
                        "target_observed": not role.get("synthetic", False),
                    })
                    self._emit_aws_edge(
                        policy_node,
                        role["node_id"],
                        "Vault_PotentialAccess",
                        caps,
                        matched_path,
                        matched_policy_path,
                        extra_properties={**merged_extra_properties, **request_properties},
                        array_property_keys=(
                            merged_array_property_keys
                            | request_array_keys
                            | {"potential_outcomes"}
                        ),
                        capability_kind=edge_kind,
                    )
                continue

            self._emit_aws_edge(
                policy_node,
                role["node_id"],
                edge_kind,
                caps,
                matched_path,
                matched_policy_path,
                extra_properties=merged_extra_properties or None,
                array_property_keys=merged_array_property_keys or None,
            )

    def _emit_aws_static_role_targets(
        self,
        policy_node: str,
        info: dict,
        role_pattern: str,
        edge_kind: str,
        caps: list[str],
        matched_path: str,
        matched_policy_path: str,
        create_synthetic_if_missing: bool = False,
        extra_properties: dict[str, Any] | None = None,
        array_property_keys: set[str] | None = None,
    ):
        matched_roles = self._match_aws_static_roles(info["accessor"], role_pattern)
        if not matched_roles and create_synthetic_if_missing and not self._pki_is_globbed(role_pattern):
            matched_roles = [self._ensure_aws_static_role(info["accessor"], info, role_pattern)]

        for role in matched_roles:
            merged_extra_properties = dict(extra_properties or {})
            merged_array_property_keys = set(array_property_keys or set())
            if edge_kind == "Vault_AwsManageStaticRole":
                operations = merged_extra_properties.get("operations") or []
                if "write" in operations:
                    merged_extra_properties["write_effects"] = self._aws_static_role_write_effects(role)
                    merged_array_property_keys.add("write_effects")
            self._emit_aws_edge(
                policy_node,
                role["node_id"],
                edge_kind,
                caps,
                matched_path,
                matched_policy_path,
                extra_properties=merged_extra_properties or None,
                array_property_keys=merged_array_property_keys or None,
            )

    def _emit_aws_mount_broad_edges(
        self,
        policy_node: str,
        info: dict,
        caps: list[str],
        matched_path: str,
        matched_policy_path: str | None = None,
    ):
        policy_path = matched_policy_path or matched_path
        mount_node = info["node_id"]
        self._emit_supported_engine_broad_object_edges(policy_node, info, caps, matched_path, policy_path)

        if "list" in caps:
            for edge_kind in ("Vault_AwsListRoles", "Vault_AwsListStaticRoles"):
                self._emit_aws_edge(
                    policy_node,
                    mount_node,
                    edge_kind,
                    caps,
                    matched_path,
                    policy_path,
                )

        if "read" in caps:
            for edge_kind in (
                "Vault_AwsReadRootConfig",
                "Vault_AwsReadLeaseConfig",
                "Vault_AwsReadRole",
                "Vault_AwsReadStaticRole",
                "Vault_AwsGetStaticCredentials",
            ):
                self._emit_aws_edge(
                    policy_node,
                    mount_node,
                    edge_kind,
                    caps,
                    matched_path,
                    policy_path,
                )
            creds_properties, creds_array_keys = self._aws_credential_request_properties(None, "creds")
            self._emit_aws_edge(
                policy_node,
                mount_node,
                "Vault_AwsGenerateCredentials",
                caps,
                matched_path,
                policy_path,
                extra_properties=creds_properties,
                array_property_keys=creds_array_keys,
            )

        if filter_capabilities(caps, {"create", "update"}):
            sts_properties, sts_array_keys = self._aws_credential_request_properties(None, "sts")
            self._emit_aws_edge(
                policy_node,
                mount_node,
                "Vault_AwsGenerateStsCredentials",
                caps,
                matched_path,
                policy_path,
                extra_properties=sts_properties,
                array_property_keys=sts_array_keys,
            )
            self._emit_aws_edge(
                policy_node,
                mount_node,
                "Vault_AwsRotateRoot",
                caps,
                matched_path,
                policy_path,
                extra_properties={
                    "requires_static_root_credentials": True,
                    "requires_single_access_key": True,
                    "preconditions": [
                        "Static Root Credentials",
                        "Single Active AWS Access Key",
                    ],
                },
                array_property_keys={"preconditions"},
            )

        root_manage_operations = self._aws_manage_operations(caps, include_delete=False)
        if root_manage_operations:
            self._emit_aws_edge(
                policy_node,
                mount_node,
                "Vault_AwsManageRootConfig",
                caps,
                matched_path,
                policy_path,
                extra_properties={"operations": root_manage_operations},
                array_property_keys={"operations"},
            )

        role_manage_operations = self._aws_role_manage_operations(caps)
        if role_manage_operations:
            self._emit_aws_edge(
                policy_node,
                mount_node,
                "Vault_AwsManageRole",
                caps,
                matched_path,
                policy_path,
                extra_properties={"operations": role_manage_operations},
                array_property_keys={"operations"},
            )

        static_role_manage_operations = self._aws_manage_operations(caps)
        if static_role_manage_operations:
            merged_extra_properties: dict[str, Any] = {"operations": static_role_manage_operations}
            merged_array_property_keys = {"operations"}
            if "write" in static_role_manage_operations:
                merged_extra_properties["write_effects"] = aws_static_role_write_effects({})
                merged_array_property_keys.add("write_effects")
            self._emit_aws_edge(
                policy_node,
                mount_node,
                "Vault_AwsManageStaticRole",
                caps,
                matched_path,
                policy_path,
                extra_properties=merged_extra_properties,
                array_property_keys=merged_array_property_keys,
            )

        lease_manage_operations = self._aws_manage_operations(caps, include_delete=False)
        if lease_manage_operations:
            self._emit_aws_edge(
                policy_node,
                mount_node,
                "Vault_AwsManageLeaseConfig",
                caps,
                matched_path,
                policy_path,
                extra_properties={"operations": lease_manage_operations},
                array_property_keys={"operations"},
            )

    def _iter_azure_roles(self, accessor: str) -> list[dict[str, Any]]:
        return sorted(
            self._azure_roles.get(accessor, {}).values(),
            key=lambda role: role["name"],
        )

    def _match_azure_roles(self, accessor: str, pattern: str) -> list[dict[str, Any]]:
        return [
            role for role in self._iter_azure_roles(accessor)
            if policy_path_matches_resource_path(pattern, role["name"])
        ]

    def _ensure_azure_role(
        self,
        accessor: str,
        info: dict,
        role_name: str,
    ) -> dict[str, Any]:
        roles = self._azure_roles.setdefault(accessor, {})
        if role_name in roles:
            return roles[role_name]

        role_info = self._build_azure_role_info(accessor, info, role_name, {}, synthetic=True)
        roles[role_name] = role_info
        self.nodes.append(GraphNode(
            id=role_info["node_id"],
            kinds=get_azure_role_kinds(),
            properties=role_info["properties"],
        ))
        self.edges.append(GraphEdge(
            source=info["node_id"],
            target=role_info["node_id"],
            kind="Vault_AzureContainsRole",
        ))
        return role_info

